import catalog from "./assets/space-covers/catalog.json";
import shellMore from "./i18n/shell-more";
import type { ChoiceOption } from "./components/settings/types";
import { foldText } from "./lib/foldText";

/**
 * The built-in drawings as a person chooses among them: their Czech names, the four groups and the tags and stems the
 * gallery searches (assets/space-covers/catalog.json, generated by tooling/space-covers; the server embeds the same file).
 * Imported only by the settings block, which loads lazily, never by the card: showing a drawing needs only its URL
 * (spaceCoverDrawings.ts).
 */
export type SpaceCoverGroup = "it" | "business" | "industry" | "general";
/** `stems`: the beginnings of words the server matches a space's name with (lower case, no diacritics), such as "zaloh". */
export interface SpaceCoverEntry { id: string; name: string; group: SpaceCoverGroup; tags: string[]; stems: string[] }

/** In catalog order. */
export const spaceCoverEntries: readonly SpaceCoverEntry[] = catalog.map(({ id, name, group, tags, stems }) => ({ id, name, group: group as SpaceCoverGroup, tags, stems: stems.map((stem) => foldText(stem)) }));
export const spaceCoverGroupOptions: ChoiceOption[] = [
  { value: "", get label() { return shellMore.cover.all; }, icon: "layers" },
  { value: "it", label: "IT", icon: "server" },
  { value: "business", get label() { return shellMore.cover.company; }, icon: "building-2" },
  { value: "industry", get label() { return shellMore.cover.field; }, icon: "activity" },
  { value: "general", get label() { return shellMore.cover.general; }, icon: "lightbulb" },
];
export const spaceCoverName = (key: string | null | undefined) => (key ? spaceCoverEntries.find((entry) => entry.id === key)?.name : undefined);

/**
 * Every word of the query must be found, without diacritics: anywhere in the names and tags, or, from three characters
 * on, in a stem, so "záloha" finds Zálohy a obnova. The word may be the beginning of a stem or go on after it; as for
 * the server, a stem of at most three characters stands for that whole word only ("pr" does not begin "provoz").
 * "" group = all.
 */
export function findSpaceCovers(query: string, group: string): SpaceCoverEntry[] {
  const words = foldText(query.trim()).split(/\s+/).filter(Boolean);
  return spaceCoverEntries.filter((entry) => {
    if (group && entry.group !== group) return false;
    const haystack = foldText(`${entry.name} ${entry.tags.join(" ")}`);
    return words.every((word) => haystack.includes(word)
      || (word.length >= 3 && entry.stems.some((stem) => stem.startsWith(word) || (stem.length > 3 && word.startsWith(stem)))));
  });
}
